Keep `FeedModel` on the main actor, use `URLSession` for the download, and put parsing in an `@concurrent` helper so synchronous parsing doesn’t block the UI.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var error: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }

        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            let parsed = try await Self.fetchItems(from: feedURL)
            try Task.checkCancellation()
            items = parsed
        } catch {
            if !Task.isCancelled {
                self.error = error
            }
        }
    }

    @concurrent
    private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, response) = try await URLSession.shared.data(from: url)

        if let http = response as? HTTPURLResponse,
           !(200..<300).contains(http.statusCode) {
            throw URLError(.badServerResponse)
        }

        try Task.checkCancellation()
        return Parser.parse(data)
    }
}
```

In a main-actor-by-default target, mark a stateless parser’s `parse` method `nonisolated`, or mark the entire `Parser` type `nonisolated` if none of it needs the main actor. Make `Item` a `Sendable` value type so `[Item]` can cross back to the main actor. If `parse` throws, use `return try Parser.parse(data)`.

In SwiftUI, call it with `.task { await model.load() }` so SwiftUI can cancel the load when the view disappears. `@concurrent` is the key Swift 6.2 detail: `async` alone doesn’t move synchronous parsing off the main actor.

Use `URLSession` for the download, keep the published state on the main actor, and put synchronous parsing behind a Swift 6.2 `@concurrent` function so it doesn’t block the UI.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = try await Self.parseOffMain(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as URLError.cancelled.
            if !Task.isCancelled {
                loadError = error
            }
        }
    }

    @concurrent
    private static func parseOffMain(_ data: Data) async throws -> [Item] {
        try Parser.parse(data)
    }
}
```

The model is implicitly `@MainActor` under your target setting, so `load()` can update its properties directly after each `await`. `URLSession` already suspends during network I/O; `@concurrent` is for the CPU-bound parsing step.

Make sure `Parser.parse` is `nonisolated` (or declare `Parser` itself `nonisolated` if the whole type is safe to use off-main), and that `Item` is `Sendable` so the array can cross back to the main actor. If `Parser.parse` is nonthrowing, remove `throws` and the two `try`s associated with `parseOffMain`.

In SwiftUI, call it with `.task { await model.load() }` so the view owns the task’s lifetime. Cancellation prevents publishing a stale result; it won’t interrupt a synchronous parser that’s already running unless the parser itself checks for cancellation.

Make `load()` async, use `URLSession` for the download, and put synchronous parsing in an `@concurrent` helper. With Main Actor default isolation, the model can update its published properties directly—even after an `await`.

```swift
